solution.javascript:
function existeSuma(nums, objetivo) {
  const n = nums.length;
  for (let mask = 0; mask < (1 << n); mask++) {
    let suma = 0;
    for (let i = 0; i < n; i++) if (mask & (1 << i)) suma += nums[i];
    if (suma === objetivo) return true;
  }
  return false;
}

solution.python:
def existeSuma(nums, objetivo):
    n = len(nums)
    for mask in range(1 << n):
        suma = sum(nums[i] for i in range(n) if mask & (1 << i))
        if suma == objetivo:
            return True
    return False
